import{STATUS_LABELS as p}from"./labels.min.js";export const CARD_ATLAS={cols:8,cellW:256,cellH:160};export function boardColumns(n){return n.statuses.map(t=>({status:t,label:p[t]}))}export function boardPlan(n,t){const c=boardColumns(t).map(o=>({...o,ids:[]})),e=new Map(c.map((o,r)=>[o.status,r]));for(const o of n){const r=e.get(o.app.status);r!=null&&c[r].ids.push(o.app.id)}return c}export function cardSlots(n){const t=new Map;return n.forEach((c,e)=>c.ids.forEach((o,r)=>t.set(o,{column:e,index:r,count:c.ids.length}))),t}export function columnZ(n,t,c){const e=t.width/c;return t.z+t.width/2-e*(n+.5)}export function columnAt(n,t,c){const e=t.width/c,o=Math.floor((t.z+t.width/2-n)/e);return Math.min(c-1,Math.max(0,o))}export function cardPose(n,t,c){const e=t.y+t.height/2-t.header-t.card[1]/2-.02,o=t.height-t.header-t.card[1]-.04,r=n.count>1?Math.min(t.card[1]+.012,o/(n.count-1)):0;return{y:e-r*n.index,z:columnZ(n.column,t,c),depth:.004+n.index*.0012}}export function cardTilt(n){let t=0;for(let c=0;c<n.length;c++)t=t*31+n.charCodeAt(c)>>>0;return(t%1e3/1e3-.5)*.08}export function cardCorners(n,t,c=0){const e=t[0]/2,o=t[1]/2,r=Math.cos(c),s=Math.sin(c);return[[-e,-o],[e,-o],[e,o],[-e,o]].map(([h,u])=>{const i=h*r-u*s,a=h*s+u*r;return[n.y+a,n.z-i]})}export function cardUvs(n,t,c=CARD_ATLAS){const e=n%c.cols,o=Math.floor(n/c.cols),r=e/c.cols,s=(e+1)/c.cols,h=1-o/t,u=1-(o+1)/t;return[[r,u],[s,u],[s,h],[r,h]]}export function atlasRows(n,t=2,c=CARD_ATLAS){return Math.max(t,Math.ceil(n/c.cols))}export function carryPose(n,t,c,e=.1){const o=Math.min(1,Math.max(0,c));if(o>=1)return{...t};if(o<=0)return{...n};const r=o*o*(3-2*o),s=n.y!==t.y||n.z!==t.z;return{y:n.y+(t.y-n.y)*r,z:n.z+(t.z-n.z)*r,depth:n.depth+(t.depth-n.depth)*r+(s?Math.sin(Math.PI*o)*e:0)}}export function boardSummary(n){const t=n.filter(c=>c.ids.length).map(c=>`${c.label} ${c.ids.length}`);return t.length?`On the board: ${t.join(", ")}.`:"The board is empty."}
